import { chooseActivity, compareRoutes, lateralMove, sameRequest } from './activity.mjs';
import { ACTIVITIES, rank, resolveRoute, routeSpec, TIERS } from './config.mjs';
import * as costs from './cost.mjs';
import { clip, extractFacts, verifiedSince } from './facts.mjs';
import { CONTEXT_FILL, decide, fitTier, initialState } from './policy.mjs';

// Exact observed API snapshot, not a rule that merges different dated versions.
const SNAPSHOTS = { 'claude-haiku-4-5': 'claude-haiku-4-5-20251001' };

// A request this much smaller than the last means the history was compacted or rewound: the cached prefixes the
// observations describe are gone, so they are dropped rather than priced as warm.
export const HISTORY_SHRINK = 0.8;

// Whether the engine served the requested model, allowing for a dated snapshot of it.
export function isSameModel(requested, served) {
  return requested === served || SNAPSHOTS[requested] === served;
}

// The engine may echo our own routed model on a continuation; any third model is its fallback.
export function isNativeFallback(loop, model) {
  if (loop.suspended) return true;
  const known = [loop.engineModel, loop.decision?.model].filter(Boolean);
  return known.length > 0 && !known.some((id) => isSameModel(id, model));
}

// The tier and activity whose route runs model `id`, or null when no route names it. Base routes first, baseline
// first; activity overrides only when they apply, with `activityRouting: on`.
export function cellForModel(config, id) {
  const order = [config.baselineTier, ...TIERS.filter((tier) => tier !== config.baselineTier)];
  const runs = (tier, activity) => isSameModel(routeSpec(config, resolveRoute(config, tier, activity)).id, id);
  const tier = order.find((t) => runs(t, null));
  if (tier) return { tier, activity: null };
  if (config.activityRouting !== 'on') return null;
  for (const t of order)
    for (const activity of ACTIVITIES)
      if (config.activities[activity]?.[t] && runs(t, activity)) return { tier: t, activity };
  return null;
}

export function emptyLoop(config, model) {
  const cell = cellForModel(config, model);
  return {
    lastRoute: cell?.tier ?? config.baselineTier,
    lastActivity: cell?.activity ?? null,
    state: initialState(),
    models: {},
    resolutions: {},
    lastRequest: null,
    historyMeasured: false,
    lastMessageCount: null,
    generation: 0,
    turnId: null,
    decision: null,
    ineligible: [],
    // Routed main requests so far, the one that started on the running route (`switchedAt`: requests and message
    // count then), and the request count at the last classifier answer (`reviewedAt`). Dwell and reviews count these.
    requests: 0,
    servedRoute: null,
    switchedAt: null,
    reviewedAt: 0,
    // The message count at the last review applied inside a turn: tool calls before it were already judged, so only
    // later ones can move the route up again (observedMove).
    observedFrom: 0,
    // Each configured model's simulated cache, by models key, for the routing-vs-your-model readout (compareModels in
    // savings.mjs).
    yoursBy: {},
  };
}

const freshState = (state) => ({ ...state, votes: [], holdUntilTurn: 0, escalatedSignature: null });

export function resetHistory(loop) {
  return {
    ...loop,
    generation: loop.generation + 1,
    models: {},
    resolutions: {},
    historyMeasured: false,
    state: freshState(loop.state),
    // The active turn keeps its route, pin and fallback suspension; the next turn decides afresh.
    ineligible: [],
    yoursBy: {},
  };
}

export function prepareLoop(loop, messageCount) {
  if (loop.lastMessageCount === null || messageCount >= loop.lastMessageCount)
    return { ...loop, lastMessageCount: messageCount };
  // Compaction or a rewind shortened the history: message cursors past its end move to it, so checks and edits made
  // from here on count. The request-based dwell is kept.
  const cursor = (count) => Math.min(count ?? 0, messageCount);
  return {
    ...resetHistory(loop),
    lastMessageCount: messageCount,
    switchedAt: loop.switchedAt && { ...loop.switchedAt, messageCount: cursor(loop.switchedAt.messageCount) },
    observedFrom: cursor(loop.observedFrom),
  };
}

export function nativeFacts(config, loop, { messages, prompt, effort, turnId, contextTokens }) {
  const facts = extractFacts({ messages, output_config: { effort } }, loop, config.context);
  if (typeof prompt === 'string') facts.prompt = clip(prompt, config.context.maxTextChars);
  // A move down on the same task waits out the dwell and for a passed verification since the last model change.
  const since = loop.switchedAt ?? { requests: 0, messageCount: 0 };
  const downAllowed =
    (loop.requests ?? 0) - since.requests >= config.policy.minDwellRequests &&
    verifiedSince(messages, since.messageCount);
  // A loop saved without the field counts as measured, keeping the vote streak.
  return {
    ...facts,
    downAllowed,
    pin: null,
    contextTokens,
    turnKey: turnId,
    historyMeasured: loop.historyMeasured !== false,
  };
}

export function isModelAllowed(id, available, nativeModel) {
  if (available === undefined) return true;
  if (!Array.isArray(available) || !available.every((v) => typeof v === 'string')) return false;
  if (available.includes('default') && id === nativeModel) return true;
  const family = /^claude-(opus|sonnet|haiku)-/.exec(id)?.[1];
  const specific = available.filter((v) => family && v.startsWith(`claude-${family}-`));
  if (specific.length) return specific.some((v) => id === v || id.startsWith(`${v}-`));
  return available.some((v) => id === v || id.startsWith(`${v}-`) || (family && v === family));
}

function economicConfig(config, loop) {
  const models = Object.fromEntries(
    Object.entries(config.models).map(([alias, model]) => [
      alias,
      { ...model, id: Object.hasOwn(loop.resolutions, model.id) ? loop.resolutions[model.id] : model.id },
    ]),
  );
  return { ...config, models };
}

// `activityRouting` decides which activity the route may use: none in `off`, the chosen one in `on`.
export function chooseRoute(config, loop, input) {
  const { pin, facts } = input;
  const applied = routeTurn(config, loop, input);
  const kept = pin || !applied.tier;
  return {
    ...loop,
    state: applied.state,
    lastRoute: kept ? loop.lastRoute : applied.tier,
    lastActivity: kept ? activityOf(config, loop) : applied.activity,
    turnId: facts.turnKey,
    decision: applied,
    suspended: false,
    reviewedAt: loop.requests ?? 0,
  };
}

// The activity of the route running now. Outside `on` there is none, even one a turn in `on` left in the loop before
// the mode changed: `off` is the 1.5 decision.
const activityOf = (config, loop) => (config.activityRouting === 'on' ? (loop.lastActivity ?? null) : null);

// One decision (plan §5.2) for the cell `{ tier, activity }` it lands on. Outside `on` the activity is null throughout.
function routeTurn(config, loop, { facts, advice, pin, nativeModel, contextKnown, availableModels, now }) {
  const projected = economicConfig(config, loop);
  const routeOf = (cell) => resolveRoute(config, cell.tier, cell.activity);
  const specOf = (cell) => routeSpec(config, routeOf(cell));
  const last = { tier: loop.lastRoute, activity: activityOf(config, loop) };
  const tier0 = TIERS.includes(facts.lastRoute) ? facts.lastRoute : config.baselineTier;
  const incumbent = { tier: tier0, activity: last.activity, route: resolveRoute(config, tier0, last.activity) };
  const activity =
    pin || config.activityRouting !== 'on' ? null : chooseActivity(config, advice, incumbent, facts.effort, facts);
  let result =
    pin && TIERS.includes(pin)
      ? {
          tier: pin,
          activity: null,
          reason: 'pinned',
          lateral: null,
          escalated: false,
          state: { ...loop.state, turn: loop.state.turn + 1 },
        }
      : decideCell({ config, projected, facts, advice, state: loop.state, now, incumbent, activity });
  // Without a reliable reading of the context, a route with a smaller window than the last one might overflow.
  const shrinksUnmeasured = (cell) =>
    (!contextKnown || !loop.historyMeasured) && specOf(cell).contextWindow < specOf(last).contextWindow;
  const fits = (cell) => {
    const model = specOf(cell);
    return (
      !shrinksUnmeasured(cell) &&
      isModelAllowed(model.id, availableModels, nativeModel) &&
      !loop.ineligible.includes(model.id) &&
      (!contextKnown || costs.nextContextTokens(facts) <= model.contextWindow * CONTEXT_FILL)
    );
  };
  if (contextKnown) {
    const routeFor = (tier) => resolveRoute(config, tier, result.activity);
    const fitted = fitTier(config, result.tier, costs.nextContextTokens(facts), routeFor);
    if (fitted !== result.tier) result = { ...result, tier: fitted, reason: 'context-fit', lateral: null };
  }
  // A lateral outcome describes the cell the lateral rule chose; a context or availability override replaces it.
  if (shrinksUnmeasured(result)) result = { ...result, ...last, reason: 'context-unknown', lateral: null };
  if (!fits(result)) {
    // A cell labelled with another activity would run, and stick, a route this turn did not choose.
    const native = cellForModel(config, nativeModel);
    const cells = [last, native, ...TIERS.map((tier) => ({ tier, activity }))];
    const fallback = cells.find(
      (cell) => cell && (cell.activity === null || cell.activity === activity) && fits(cell),
    ) ?? { tier: null, activity: null };
    result = { ...result, ...fallback, reason: 'model-unavailable', lateral: null };
  }
  const route = result.tier ? routeOf(result) : null;
  const model = route ? routeSpec(config, route).id : nativeModel;
  const effort = route ? costs.routeEffort(config, route, facts.effort) : facts.effort;
  let comparison = null;
  const candidate = pin ?? advice?.choice;
  if (contextKnown && loop.lastRequest && TIERS.includes(candidate) && candidate !== loop.lastRoute) {
    const [to, from] = [resolveRoute(config, candidate, activity), routeOf(last)];
    const forecast = costs.switchEconomics(projected, to, from, facts, now);
    comparison = {
      candidate,
      incumbent: loop.lastRoute,
      ...costs.nextTurnRange(projected, to, from, facts, now),
      paybackTurns: forecast?.paybackTurns ?? null,
      outputTokens: loop.lastRequest.outputTokens,
    };
  }
  return { ...result, model, effort, comparison, pinned: Boolean(pin), requestedPin: pin ?? null };
}

// Steps 3-6 of plan §5.2: the tier as `decide` picks it, every candidate priced at its route for `activity` and the
// incumbent at the route it runs; then, when the tier stays and the route would change, the lateral rule. Equal routes
// never switch: a label alone decides nothing.
function decideCell({ config, projected, facts, advice, state, now, incumbent, activity }) {
  const routeFor = (tier) => resolveRoute(config, tier, activity);
  // With an activity, failures move to the lowest tier whose route is stronger, or another request that does not
  // order against it; with none, one tier up as before.
  const escalates = (t) => {
    const order = compareRoutes(config, routeFor(t), incumbent.route, facts.effort);
    return order > 0 || (order === null && !sameRequest(config, routeFor(t), incumbent.route, facts.effort));
  };
  const escalateTo = activity === null ? undefined : (tier) => TIERS.slice(rank(tier) + 1).find(escalates) ?? null;
  const step = decide({
    config: projected,
    facts,
    advice,
    state,
    baseline: config.baselineTier,
    now,
    costs,
    routeFor,
    incumbentRoute: incumbent.route,
    escalateTo,
  });
  // `decide` takes the failure's signature whenever it escalates, before the cash gate can hold the move; a later
  // context or availability override keeps the flag.
  const escalated = step.state.escalatedSignature !== state.escalatedSignature;
  const route = routeFor(step.tier);
  if (step.tier !== incumbent.tier || sameRequest(config, route, incumbent.route, facts.effort))
    return { ...step, activity, lateral: null, escalated };
  const lateral = lateralMove({
    config: projected,
    from: incumbent.route,
    to: route,
    // Returning to the base route needs no evidence.
    mass: activity === null ? 1 : (advice?.activity?.probabilities?.[activity] ?? 0),
    hold: step.reason === 'hold',
    facts,
    now,
    costs,
  });
  const activityOf = lateral.move ? activity : incumbent.activity;
  return {
    ...step,
    activity: activityOf,
    reason: lateral.reason,
    estimate: lateral.estimate,
    lateral: lateral.move ? 'taken' : 'refused',
    escalated,
  };
}

// Whether some activity's route at the decision's tier is stronger than the one running: only then can the turn's own
// tool calls move it (observedMove), so a step on the strongest route skips reading the transcript.
export function canMoveUp(config, decision, effort) {
  if (config.activityRouting !== 'on' || !decision?.tier || decision.pinned) return false;
  const from = resolveRoute(config, decision.tier, decision.activity ?? null);
  return ACTIVITIES.some((a) => compareRoutes(config, resolveRoute(config, decision.tier, a), from, effort) > 0);
}

// A move up inside a turn: the classifier labels a turn from its prompt, and a prompt that reads as ops or explore can
// still end up editing code. Once the turn's tool calls show an activity (observedActivity in facts.mjs) whose route at the
// tier is stronger, the remaining steps take that route. The tools are the evidence, so the move needs no classifier
// probability. At probability 1 the switching tax never holds it back (the upgrade bar tops out near 0.9): only the
// cash gate, priced at the context-fitted route, can. Only up: a move down comes from a classifier review, past its
// checks. Returns the loop, unchanged when nothing moves.
export function observedMove(config, loop, { observed, facts, contextKnown, now }) {
  const decision = loop.decision;
  if (!canMoveUp(config, decision, facts.effort) || !ACTIVITIES.includes(observed)) return loop;
  const from = resolveRoute(config, decision.tier, decision.activity ?? null);
  // The gates price the route that will run: the one the context fits, not the tier's first choice.
  const routeFor = (tier) => resolveRoute(config, tier, observed);
  const tier = fitTier(config, decision.tier, costs.nextContextTokens(facts), routeFor);
  const to = routeFor(tier);
  if (!(compareRoutes(config, to, from, facts.effort) > 0)) return loop;
  // Without a reliable reading of the context, a smaller window might overflow, as in routeTurn.
  const window = (route) => routeSpec(config, route).contextWindow;
  if ((!contextKnown || !loop.historyMeasured) && window(to) < window(from)) return loop;
  const projected = economicConfig(config, loop);
  const lateral = lateralMove({ config: projected, from, to, mass: 1, hold: false, facts, now, costs });
  if (!lateral.move) return loop;
  return {
    ...loop,
    lastActivity: observed,
    decision: {
      ...decision,
      tier,
      activity: observed,
      model: routeSpec(config, to).id,
      effort: costs.routeEffort(config, to, facts.effort),
      reason: lateral.reason,
      estimate: lateral.estimate,
    },
  };
}

// A tool continuation keeps the turn's route and activity; only the context, the model list, or the turn's own tool
// calls (observedMove) can move it.
export function continueRoute(config, loop, { nativeModel, contextTokens, contextKnown, availableModels, effort }) {
  if (!loop.decision) return loop;
  let decision = loop.decision;
  if (contextKnown && decision.tier) {
    const routeOf = (tier) => resolveRoute(config, tier, decision.activity ?? null);
    const fitted = fitTier(config, decision.tier, contextTokens, routeOf);
    if (fitted !== decision.tier)
      decision = {
        ...decision,
        tier: fitted,
        model: routeSpec(config, routeOf(fitted)).id,
        effort: costs.routeEffort(config, routeOf(fitted), effort),
        reason: 'context-fit',
      };
  }
  if (!isModelAllowed(decision.model, availableModels, nativeModel) || loop.ineligible.includes(decision.model)) {
    decision = { ...decision, tier: null, activity: null, model: nativeModel, effort, reason: 'model-unavailable' };
  }
  return { ...loop, decision };
}

export function observeResponse(config, loop, { usage, requestedModel, effort, stopReason, now }) {
  // Every request counts toward dwell and reviews; a request on another (model, effort) than the last starts a dwell,
  // and so does the first one this loop serves: checks from before it ran on a route the router did not choose.
  const served = `${requestedModel}@${effort ?? 'session'}`;
  const requests = (loop.requests ?? 0) + 1;
  const switched = loop.servedRoute !== served;
  let next = {
    ...loop,
    requests,
    servedRoute: served,
    switchedAt: switched ? { requests, messageCount: loop.lastMessageCount ?? 0 } : (loop.switchedAt ?? null),
  };
  if (stopReason === 'model_context_window_exceeded') {
    next = { ...next, ineligible: [...new Set([...next.ineligible, requestedModel])] };
  }
  if (!usage?.model) return next;
  const sameModel = isSameModel(requestedModel, usage.model);
  if (!sameModel) next = { ...next, suspended: true };
  const counts = ['input_tokens', 'cache_read_input_tokens', 'cache_creation_input_tokens', 'output_tokens'];
  if (!counts.every((key) => Number.isFinite(usage[key]) && usage[key] >= 0)) return next;
  const tokens = usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens;
  if (tokens === 0) return next;
  const resolutions = sameModel ? { ...next.resolutions, [requestedModel]: usage.model } : { ...next.resolutions };
  if (!sameModel) delete resolutions[requestedModel];
  let models = next.models;
  if (next.lastRequest && tokens < next.lastRequest.tokens * HISTORY_SHRINK) models = {};
  // A substituted model's effort is not reported, so do not credit its estimated cache.
  if (sameModel)
    models = {
      ...models,
      [costs.cacheKey(config, usage.model, effort)]: {
        lastAt: now,
        prefixTokens: usage.cache_read_input_tokens + usage.cache_creation_input_tokens,
      },
    };
  return {
    ...next,
    historyMeasured: true,
    models,
    resolutions,
    lastRequest: {
      model: usage.model,
      tokens,
      outputTokens: usage.output_tokens,
      cacheReadTokens: usage.cache_read_input_tokens,
      cacheWriteTokens: usage.cache_creation_input_tokens,
      at: now,
    },
  };
}

files.lib/savings.mjs:
// Routing vs your model: what each main reply cost at configured list prices on the model that served it, against
// the same tokens on the session's own model and effort ("your model"). Counts and dollars only, never text. Pure:
// the hook feeds each reply, keeps the session totals in the view, and keeps each reply by day in usage.mjs's
// records. The records under SAVINGS_PREFIX are undated history from before those, read and never written.

import { effortSharesCache, ratesAt } from './cost.mjs';
import { afterResetOf, earlierSince, isRecord } from './records.mjs';
import { HISTORY_SHRINK, isSameModel } from './route.mjs';

// Each session kept its own record under this prefix and its session id, as usage.mjs's records are now kept.
export const SAVINGS_PREFIX = 'savings:v1:';
// When Delete history last ran (ms), from any session: a session may still hold its record from before and write it back.
// The activity metrics records (METRICS_PREFIX) use it too.
export const SAVINGS_RESET_KEY = 'savings:reset:v1';
// Fewer replies than this read "too early": one switch and its cache write dominate a short run.
export const EARLY_REPLIES = 10;
const TTLS = ['5m', '1h'];

// The model entry an API model id runs on: its configured id, a dated snapshot of it, or the id with a context
// suffix such as `[1m]`. Null when no entry prices it.
export function modelSpec(config, id) {
  if (typeof id !== 'string') return null;
  const bare = id.replace(/\[[^\]]*\]$/, '');
  const dated = (model) => bare.startsWith(model.id) && /^-\d{8}$/.test(bare.slice(model.id.length));
  return Object.values(config.models).find((model) => isSameModel(model.id, bare) || dated(model)) ?? null;
}

// A by-model record's own entry for a models key, else undefined: router.json may name a model `toString`, which a
// plain object would otherwise answer from its prototype, or `null`, which a missing alias would coerce to.
export const modelEntry = (byModel, alias) =>
  typeof alias === 'string' && byModel && Object.hasOwn(byModel, alias) ? byModel[alias] : undefined;

// The router.json models key (`opus`) of the entry an API model id runs on, or null.
export function modelAlias(config, id) {
  const spec = modelSpec(config, id);
  return spec ? (Object.keys(config.models).find((alias) => config.models[alias] === spec) ?? null) : null;
}

// One request's list price in USD: `counts` are its uncached input, cache read, cache write and output tokens, the
// writes at `writeMultiplier` times input. Long-context rates follow the whole prompt.
export function requestUsd(model, { input, cacheRead, cacheWrite, output }, writeMultiplier) {
  const rates = ratesAt(model, input + cacheRead + cacheWrite);
  return (
    (rates.input * (input + cacheWrite * writeMultiplier) + rates.cacheRead * cacheRead + rates.output * output) / 1e6
  );
}

const truthy = (value) => /^(1|true|yes|on)$/i.test(String(value ?? '').trim());

// The prompt-cache lifetime Claude Code gives the main conversation, by its own rule as of 2.1.296: FORCE_PROMPT_CACHING_5M,
// then CLAUDE_CODE_PROMPT_CACHE_TTL, then the `promptCacheTtl` setting, then ENABLE_PROMPT_CACHING_1H, then one hour
// for a Claude plan subscriber and five minutes otherwise. Its usage reports carry no 5m/1h split, so this is how the
// writes are priced. Limit: a subscriber billed as overage gets five minutes, which this cannot see.
export function sessionCacheTtl({ force5m, envTtl, settingTtl, enable1h, subscriber }) {
  if (truthy(force5m)) return '5m';
  if (TTLS.includes(envTtl)) return envTtl;
  if (TTLS.includes(settingTtl)) return settingTtl;
  if (truthy(enable1h) || subscriber) return '1h';
  return '5m';
}

// A subagent's prompt-cache lifetime, by Claude Code's rule for requests outside the main conversation: the same order
// with CLAUDE_CODE_SUBAGENT_PROMPT_CACHE_TTL and `subagentPromptCacheTtl`, and five minutes on a subscription too.
// Limit: an agent's `experimental.cacheTtl` frontmatter is not visible to a Mod.
export const subagentCacheTtl = ({ force5m, envTtl, settingTtl, enable1h }) =>
  sessionCacheTtl({ force5m, envTtl, settingTtl, enable1h, subscriber: false });

const isCount = (n) => Number.isFinite(n) && n >= 0;

// One main reply. `state` is your model's simulated cache: `{ total, at, onYours, model, effort }` after a reply, or
// null at the session start and after a compaction, which counts as on your model with nothing cached; a state of
// another model or effort (after `/model` or an effort change) counts as null. `served` is the route the
// reply ran on, `{ model, effort }` with the API's model id; `yours` the session's model and effort.
//
// Routed is the reply's usage on the served model. Yours is the same tokens on your model: while this reply and the
// one before it both ran on your route, the usage itself, so equal routes differ by exactly 0. Otherwise a single
// cache that never switched: it reads the previous prompt, up to this one less its uncached input, if that is inside
// the cache lifetime and no compaction shrank the history, and never less than the API actually read (a shared
// system-prompt cache, a lifetime longer than assumed); it writes the rest. Output tokens stay the same.
//
// The difference splits into the model price (the served model on your cache, against yours: cheaper models when
// negative, stronger than yours when positive) and the cache the switches cost (routed against the served model on
// your cache), never negative. The parts sum to the difference by construction. `reply` is null when a model has no
// price or `ttl` is not a known cache lifetime.
export function compareReply(config, state, { usage, served, yours, ttl, now }) {
  const counts = {
    input: usage?.input_tokens,
    cacheRead: usage?.cache_read_input_tokens,
    cacheWrite: usage?.cache_creation_input_tokens,
    output: usage?.output_tokens,
  };
  if (!Object.values(counts).every(isCount)) return { state, reply: null };
  const total = counts.input + counts.cacheRead + counts.cacheWrite;
  const [servedSpec, yoursSpec] = [modelSpec(config, served.model), modelSpec(config, yours.model)];
  const sameModel = servedSpec ? servedSpec === yoursSpec : served.model === yours.model;
  const identity = { model: yoursSpec?.id ?? yours.model, effort: yours.effort ?? null };
  // On a model that keeps one cache across efforts (effortSharesCache), an effort-only difference is the same cache.
  const sharedEffort = effortSharesCache(config, identity.model);
  const onYours = sameModel && (sharedEffort || (served.effort ?? null) === identity.effort);
  const next = { total, at: now, onYours, ...identity };
  // A cache simulated for another model or effort of yours is none of this one's: the new one starts cold.
  const prior = state?.model === identity.model && (sharedEffort || state.effort === identity.effort) ? state : null;
  const write = config.cache.writeMultiplier[ttl];
  if (
    !servedSpec ||
    !yoursSpec ||
    !Number.isFinite(servedSpec.output) ||
    !Number.isFinite(yoursSpec.output) ||
    !Number.isFinite(write)
  )
    return { state: next, reply: null };
  const routedUsd = requestUsd(servedSpec, counts, write);
  let yoursUsd = routedUsd;
  let servedOnYoursUsd = routedUsd;
  if (!(onYours && (prior?.onYours ?? true))) {
    const warm =
      prior && now - prior.at < config.cache.ttlMs[ttl] && total >= prior.total * HISTORY_SHRINK && prior.total > 0;
    const cacheRead = Math.max(counts.cacheRead, warm ? Math.min(prior.total, total - counts.input) : 0);
    const single = { ...counts, cacheRead, cacheWrite: total - counts.input - cacheRead };
    yoursUsd = requestUsd(yoursSpec, single, write);
    servedOnYoursUsd = requestUsd(servedSpec, single, write);
  }
  const modelUsd = servedOnYoursUsd - yoursUsd;
  return {
    state: next,
    reply: {
      routedUsd,
      yoursUsd,
      cheaperUsd: Math.min(0, modelUsd),
      strongerUsd: Math.max(0, modelUsd),
      switchUsd: routedUsd - servedOnYoursUsd,
      // The model a stronger reply ran on, for "9 replies on Opus 5.5".
      strongerModel: modelUsd > 0 ? servedSpec.id : null,
    },
  };
}

// One main reply against every configured model as yours, at your effort, so the session readout can follow a
// `/model` change without replaying the session: `states` and `replies` by models key, each as compareReply returns,
// and `reply`, the prices against `yours`, the API model id /model selects now, or null.
export function compareModels(config, states, { usage, served, effort, ttl, now, yours }) {
  const out = { states: {}, replies: {}, reply: null };
  for (const [alias, model] of Object.entries(config.models)) {
    const { state, reply } = compareReply(config, modelEntry(states, alias) ?? null, {
      usage,
      served,
      yours: { model: model.id, effort },
      ttl,
      now,
    });
    out.states[alias] = state;
    if (reply) out.replies[alias] = reply;
  }
  out.reply = modelEntry(out.replies, modelAlias(config, yours)) ?? null;
  return out;
}

// Each model's session totals with this reply's prices added; models without a price for it keep theirs.
export function addReplies(byModel, replies) {
  const next = { ...byModel };
  for (const [alias, reply] of Object.entries(replies))
    next[alias] = addReply(modelEntry(next, alias) ?? emptyTotals(), reply);
  return next;
}

const SUMS = ['routedUsd', 'yoursUsd', 'cheaperUsd', 'strongerUsd', 'switchUsd'];

// A session's totals: replies and the five sums. `stronger` counts replies by the stronger model they ran on.
export function emptyTotals() {
  return {
    replies: 0,
    routedUsd: 0,
    yoursUsd: 0,
    cheaperUsd: 0,
    strongerUsd: 0,
    switchUsd: 0,
    stronger: {},
  };
}

export function addReply(totals, reply) {
  const next = { ...totals, replies: totals.replies + 1 };
  for (const sum of SUMS) next[sum] = totals[sum] + reply[sum];
  if (reply.strongerModel)
    next.stronger = { ...totals.stronger, [reply.strongerModel]: (totals.stronger[reply.strongerModel] ?? 0) + 1 };
  return next;
}

// A record kept across sessions, one session's or their sum: replies and the five sums since `since` (ms), the first
// reply after a reset.
export function emptySavingsStore() {
  return {
    version: 1,
    since: null,
    replies: 0,
    routedUsd: 0,
    yoursUsd: 0,
    cheaperUsd: 0,
    strongerUsd: 0,
    switchUsd: 0,
  };
}

const STORE_KEYS = Object.keys(emptySavingsStore());

// The stored value if it has the known shape, else an empty store: a missing, hand-edited or unknown value must not
// break a turn or the pane.
export function readSavingsStore(value) {
  const ok =
    isRecord(value) &&
    Object.keys(value).length === STORE_KEYS.length &&
    STORE_KEYS.every((key) => Object.hasOwn(value, key)) &&
    value.version === 1 &&
    (value.since === null || Number.isFinite(value.since)) &&
    Number.isSafeInteger(value.replies) &&
    value.replies >= 0 &&
    SUMS.every((sum) => Number.isFinite(value[sum]));
  return ok ? { ...value } : emptySavingsStore();
}

// A record whose first reply came before the last reset at `resetAt` (ms) reads as empty.
export const afterReset = (record, resetAt) => afterResetOf(record, resetAt, emptySavingsStore);

// The totals kept across sessions: every session's record since the last reset added up, since the earliest.
export function mergeSavingsStores(values, resetAt = null) {
  const merged = emptySavingsStore();
  for (const one of values.map((value) => afterReset(readSavingsStore(value), resetAt))) {
    merged.since = earlierSince(merged.since, one.since);
    merged.replies += one.replies;
    for (const sum of SUMS) merged[sum] += one[sum];
  }
  return merged;
}

const cents = (usd) => Math.round(usd * 100);

// What the UI shows for a set of totals, in whole cents so the shown parts add up: the difference is routed less
// yours as shown, and the switch part takes the rounding remainder. A surplus goes to the switch part if the totals
// have one, else to the stronger part if they have one, else to the cheaper part toward 0. A shortfall comes off the
// stronger part down to 0, then the cheaper part. So no part changes sign or appears from rounding alone. `early`
// below EARLY_REPLIES replies. `share` is the difference against yours; `ratio` routed over yours.
export function readout(totals) {
  const [routed, yours, cheaper, stronger] = [
    totals.routedUsd,
    totals.yoursUsd,
    totals.cheaperUsd,
    totals.strongerUsd,
  ].map(cents);
  const difference = routed - yours;
  const rest = difference - cheaper - stronger;
  const switches = totals.switchUsd ? Math.max(0, rest) : 0;
  const surplus = !totals.switchUsd && totals.strongerUsd ? Math.max(0, rest) : 0;
  const strongerShown = Math.max(0, stronger + Math.min(0, rest)) + surplus;
  return {
    replies: totals.replies,
    early: totals.replies < EARLY_REPLIES,
    routedUsd: routed / 100,
    yoursUsd: yours / 100,
    differenceUsd: difference / 100,
    cheaperUsd: (difference - strongerShown - switches) / 100,
    strongerUsd: strongerShown / 100,
    switchUsd: switches / 100,
    share: yours > 0 ? difference / yours : null,
    ratio: yours > 0 ? routed / yours : null,
  };
}

files.lib/subagents.mjs:
// Subagent routing: one model per subagent, chosen at agent.spawn before its cache exists, and the counts that show
// what that choice saves. Pure: the hook passes the spawn input, the classifier's advice and each reply's usage, and
// keeps the totals in the view and, per session, in $.store under SUBAGENT_PREFIX.

import { CLASSIFY } from './config.mjs';
import { clip } from './facts.mjs';
import { afterResetOf, earlierSince, isRecord } from './records.mjs';
import { modelSpec, requestUsd } from './savings.mjs';
import { DAY, dayKey, daysBefore, RETAIN_DAYS } from './usage.mjs';

export const SUBAGENT_PREFIX = 'subagents:v1:';
// The longest a spawn waits for the classifier. The wait delays the subagent's start, and the client's deadline race
// sleeps on $.clock, which counts against the hook's 10 s budget (HookBudget in the build types).
export const SPAWN_DEADLINE_MS = 3000;
// A spawn of a type its parent loop finished one of this recently counts as a respawn: a proxy for a retry.
export const RESPAWN_WINDOW_MS = 600_000;
// Why a spawn passes through unchanged, in the order they are checked.
// `unlisted`: a built-in router.json does not list, or a type it lists as null. `pinned`: the agent's definition names a
// model and does not set `modelRouting: auto`. `unknown`: its definition could not be found or read.
export const PASS_REASONS = ['fork', 'workflow', 'explicit', 'teammate', 'unlisted', 'pinned', 'unknown'];
// Each reason as the pane and the band show it.
export const PASS_LABEL = {
  fork: 'fork',
  workflow: 'workflow agent',
  explicit: 'explicit model',
  teammate: 'teammate',
  unlisted: 'type not routed',
  pinned: 'pinned model',
  unknown: 'no definition',
};
// Why Claude Code picked the model for each reason.
export const PASS_WHY = {
  fork: 'your model',
  workflow: 'the workflow sets it',
  explicit: 'the Agent call sets it',
  teammate: 'teammates keep theirs',
  unlisted: 'not in subagents.types',
  pinned: 'its agent file sets it',
  unknown: 'agent file not found',
};
// Built-ins that ignore CLAUDE_CODE_SUBAGENT_MODEL unless CLAUDE_CODE_SUBAGENT_MODEL_FORCE is set.
const OWN_MODEL_BUILTINS = ['Explore', 'Plan'];

// The agent definition frontmatter the router reads: `name`, `model` and `modelRouting`, from a YAML block or the
// one-line JSON object some plugin builds write. Null when the text has no frontmatter. Only top-level scalars are read.
export function agentFrontmatter(text) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---/.exec(typeof text === 'string' ? text : '');
  if (!match) return null;
  const block = match[1].trim();
  const fields = {};
  if (block.startsWith('{')) {
    try {
      Object.assign(fields, JSON.parse(block));
    } catch {
      return null;
    }
  } else
    for (const line of block.split(/\r?\n/)) {
      const pair = /^([A-Za-z][\w-]*):\s*(.*?)\s*$/.exec(line);
      if (pair) fields[pair[1]] = pair[2].replace(/\s+#.*$/, '').replace(/^(['"])(.*)\1$/, '$2');
    }
  const text_ = (value) => (typeof value === 'string' && value ? value : null);
  return { name: text_(fields.name), model: text_(fields.model), modelRouting: text_(fields.modelRouting) };
}

// Whether a definition lets the router choose its model: no model, `inherit` (the main conversation's model, which
// the router routes too), or `modelRouting: auto`, where `model` is only what runs without the router.
export const routableDefinition = (definition) =>
  !definition.model || definition.model === 'inherit' || definition.modelRouting === 'auto';

const pluginOf = (spawn) => {
  const provider = spawn.provider?.plugin;
  return typeof provider === 'string' ? provider.split('@')[0] : null;
};

// What router.json lists for this spawn's type: a models key, CLASSIFY or null, or undefined when it does not list
// it. A key without a colon names a built-in, so it matches only the engine's own agent; a `plugin:name` key matches
// only that plugin's agent (provider `plugin@marketplace`).
function listedRoute(config, spawn) {
  const { types } = config.subagents;
  const type = spawn.subagentType;
  if (typeof type !== 'string' || !Object.hasOwn(types, type)) return undefined;
  const owner = type.includes(':') ? type.slice(0, type.indexOf(':')) : 'engine';
  return pluginOf(spawn) === owner ? types[type] : undefined;
}

// How the router may route this spawn's type: `{ route }`, a models key or CLASSIFY, or `{ pass }`, a PASS_REASONS
// entry. router.json's `types` decide first, a null there excluding the type. An unlisted built-in passes, since its
// definition is not readable. Any other agent is classified when its `definition` (agentFrontmatter of its file) is
// routable, and passes when it pins a model or could not be read.
export function typeRoute(config, spawn, definition = null) {
  const listed = listedRoute(config, spawn);
  if (listed !== undefined) return listed === null ? { pass: 'unlisted' } : { route: listed };
  if (pluginOf(spawn) === 'engine') return { pass: 'unlisted' };
  if (!definition) return { pass: 'unknown' };
  return routableDefinition(definition) ? { route: CLASSIFY } : { pass: 'pinned' };
}

// The reason a spawn keeps the model core gives it, or null when the router may choose one. A fork reads the parent's
// cache on the parent's model; `model` is the Agent call's own choice; a teammate and a workflow agent are not
// rewritable (a workflow agent's model rewrite is ignored, experiments/mod-router/results/agent-spawn-probe.json).
export function passReason(config, spawn, definition = null) {
  if (spawn.fork) return 'fork';
  // Before `explicit`: a workflow agent({ model }) arrives with `model` set, and counts as a workflow agent.
  if (spawn.workflow) return 'workflow';
  if (spawn.model) return 'explicit';
  if (spawn.isTeammate) return 'teammate';
  return typeRoute(config, spawn, definition).pass ?? null;
}

// The task text the classifier sees: the description and the prompt the parent wrote, clipped like a main turn's
// prompt. Never tool results or history.
export const spawnPrompt = (config, spawn) =>
  clip(`${spawn.description ?? ''}\n${spawn.prompt ?? ''}`.trim(), config.context.maxTextChars);

// The models key a `classify` type runs on from the classifier's advice, or null (no advice: core's model). `heavy`
// only for a clearly hard task, `light` for exploration or the smallest tier, `standard` for the rest.
export function classifiedAlias(config, advice) {
  if (!advice) return null;
  const { light, standard, heavy, heavyMass } = config.subagents;
  if ((advice.probabilities?.high ?? 0) >= heavyMass) return heavy;
  const activity = advice.activity;
  const explores =
    activity?.choice === 'explore' && (activity.probabilities?.explore ?? 0) >= config.policy.activityMass;
  return explores || advice.choice === 'micro' ? light : standard;
}

// The model core runs an agent on when the router sets none: its definition's model unless that is `inherit`, else
// CLAUDE_CODE_SUBAGENT_MODEL, except for the
// built-ins that ignore it without CLAUDE_CODE_SUBAGENT_MODEL_FORCE, else the parent's model. An estimate: it does not
// apply the family-alias rule or the availableModels substitution.
export function coreModelOf(config, spawn, { envModel = null, force = false, definition = null } = {}) {
  const idOf = (model) => (Object.hasOwn(config.models, model) ? config.models[model].id : model);
  const pinned = definition?.model && definition.model !== 'inherit' ? definition.model : null;
  if (pinned && !(force && envModel)) return idOf(pinned);
  const usesEnv = envModel && envModel !== 'inherit' && (force || !OWN_MODEL_BUILTINS.includes(spawn.subagentType));
  return usesEnv ? idOf(envModel) : spawn.parentModel;
}

// How the router's model compares with core's: null when they are the same, `up` or `down` by output price, `moved`
// when either has no price.
export function moveOf(config, routedModel, coreModel) {
  if (!routedModel || !coreModel || routedModel === coreModel) return null;
  const [routed, core] = [routedModel, coreModel].map((id) => modelSpec(config, id)?.output);
  if (!Number.isFinite(routed) || !Number.isFinite(core) || routed === core) return 'moved';
  return routed > core ? 'up' : 'down';
}

// One spawn's record while its agent runs: what was decided and the priced replies since the last flush. `pass` is a
// PASS_REASONS entry or null. `choice` is the models key decided, or 'core' when the decision kept core's model.
// `move` is moveOf the routed model against core's. `actualUsd` prices each reply on the model it ran on; `otherUsd`
// the same tokens on core's estimated model, none for a pass-through.
export function spawnRecord({ sessionId, spawn, pass, choice, routedModel, coreModel, move = null, failed, respawn }) {
  return {
    sessionId,
    type: spawn.subagentType,
    pass,
    choice,
    routedModel,
    coreModel,
    move,
    failed: Boolean(failed),
    respawn: Boolean(respawn),
    counted: false,
    requests: 0,
    pricedRequests: 0,
    actualUsd: 0,
    otherUsd: 0,
  };
}

const isCount = (n) => Number.isFinite(n) && n >= 0;

// The record with one reply added. A reply is priced only when both its model and the comparison's have a price.
export function addAgentReply(config, agent, usage, ttl) {
  const counts = {
    input: usage?.input_tokens,
    cacheRead: usage?.cache_read_input_tokens,
    cacheWrite: usage?.cache_creation_input_tokens,
    output: usage?.output_tokens,
  };
  const next = { ...agent, requests: agent.requests + 1 };
  const write = config.cache.writeMultiplier[ttl];
  const actual = modelSpec(config, usage?.model);
  const other = agent.pass ? null : modelSpec(config, agent.coreModel);
  const priced = (spec) => spec && Number.isFinite(spec.output);
  if (!Object.values(counts).every(isCount) || !Number.isFinite(write) || !priced(actual)) return next;
  if (!agent.pass && !priced(other)) return next;
  next.pricedRequests += 1;
  next.actualUsd += requestUsd(actual, counts, write);
  if (other) next.otherUsd += requestUsd(other, counts, write);
  return next;
}

// A record kept across sessions, one session's or their sum, since `since` (ms), the first agent after a reset, by
// local calendar day like the usage records, so the Usage tab's period applies. A day holds `routed[type]` and
// `passed[reason]`: agents, requests and the retry proxies of the type, and per model id the agents ran on, its agents
// and their cost (`models`); a routed model also counts the agents the router moved onto it, `up` or `down` from
// core's, and core's estimated cost of the same tokens. A version 1 record, from before 1.14.0, has neither days nor
// models: it reads as `undated` totals, which only the periods without a range (session and all) count.
export function emptySubagentStore() {
  return { version: 2, since: null, days: {} };
}

const ROUTED_SUMS = ['agents', 'requests', 'pricedRequests', 'respawns', 'failures'];
const PASSED_SUMS = ['agents', 'requests', 'pricedRequests'];
const ROUTED_MODEL_SUMS = ['agents', 'moved', 'up', 'down', 'usd', 'coreUsd'];
const PASSED_MODEL_SUMS = ['agents', 'usd'];
const UNDATED_SUMS = ['agents', 'usd'];
const SUMS = {
  routed: [ROUTED_SUMS, ROUTED_MODEL_SUMS],
  passed: [PASSED_SUMS, PASSED_MODEL_SUMS],
};
// A model id the record never got.
const UNKNOWN_MODEL = 'unknown';

const zeros = (sums) => Object.fromEntries(sums.map((sum) => [sum, 0]));
const emptyCounts = (sums) => ({ ...zeros(sums), models: {} });
const emptySubagentDay = () => ({ routed: {}, passed: {} });

// A key read from the store, such as a model id `__proto__`, must neither answer from the prototype nor set it.
const own = (object, key) => (Object.hasOwn(object, key) ? object[key] : undefined);
const put = (object, key, value) =>
  Object.defineProperty(object, key, { value, enumerable: true, writable: true, configurable: true });

// The finished turn's counts of one agent added to a store at `now`, on that day: the agent once, on its first flush,
// with the model it ran on and the router's move, then its requests and prices since the last flush. Days past
// RETAIN_DAYS leave the record.
export function recordAgent(store, agent, now) {
  if (!agent.requests && agent.counted) return store;
  const first = agent.counted ? 0 : 1;
  const days = structuredClone(store.days);
  const day = days[dayKey(now)] ?? emptySubagentDay();
  const kind = agent.pass ? 'passed' : 'routed';
  const key = agent.pass ?? agent.type;
  const [sums, modelSums] = SUMS[kind];
  const counts = own(day[kind], key) ?? emptyCounts(sums);
  counts.agents += first;
  counts.requests += agent.requests;
  counts.pricedRequests += agent.pricedRequests;
  const modelId = agent.routedModel || UNKNOWN_MODEL;
  const model = own(counts.models, modelId) ?? zeros(modelSums);
  model.agents += first;
  model.usd += agent.actualUsd;
  if (!agent.pass) {
    counts.respawns += first && agent.respawn ? 1 : 0;
    counts.failures += first && agent.failed ? 1 : 0;
    model.moved += first && agent.move ? 1 : 0;
    model.up += first && agent.move === 'up' ? 1 : 0;
    model.down += first && agent.move === 'down' ? 1 : 0;
    model.coreUsd += agent.otherUsd;
  }
  put(counts.models, modelId, model);
  put(day[kind], key, counts);
  days[dayKey(now)] = day;
  const cutoff = daysBefore(now, RETAIN_DAYS);
  for (const old of Object.keys(days)) if (old < cutoff) delete days[old];
  return { version: 2, since: store.since ?? now, days, ...(store.undated ? { undated: store.undated } : {}) };
}

// The record after a flush: counted once, nothing pending.
export const flushedAgent = (agent) => ({
  ...agent,
  counted: true,
  requests: 0,
  pricedRequests: 0,
  actualUsd: 0,
  otherUsd: 0,
});

const readSums = (value, sums) =>
  isRecord(value) && sums.every((sum) => isCount(value[sum]))
    ? Object.fromEntries(sums.map((sum) => [sum, value[sum]]))
    : null;

function readCounts(value, [sums, modelSums]) {
  const counts = readSums(value, sums);
  if (!counts || !isRecord(value.models)) return null;
  counts.models = {};
  for (const [id, model] of Object.entries(value.models)) {
    const read = readSums(model, modelSums);
    if (!read) return null;
    put(counts.models, id, read);
  }
  return counts;
}

function readKind(value, kind) {
  const out = {};
  if (!isRecord(value)) return out;
  for (const [key, counts] of Object.entries(value)) {
    const read = readCounts(counts, SUMS[kind]);
    if (read) put(out, key, read);
  }
  return out;
}

const readDay = (day) => ({ routed: readKind(day.routed, 'routed'), passed: readKind(day.passed, 'passed') });

// A version 1 record's agents and their cost on the models they ran on: what is left of it without days or models.
function undatedOf(value) {
  const out = zeros(UNDATED_SUMS);
  const add = (counts, usd) => {
    if (!isRecord(counts) || !isCount(counts.agents) || !isCount(counts[usd])) return;
    out.agents += counts.agents;
    out.usd += counts[usd];
  };
  for (const counts of Object.values(isRecord(value.routed?.on) ? value.routed.on : {})) add(counts, 'routedUsd');
  for (const counts of Object.values(isRecord(value.passed) ? value.passed : {})) add(counts, 'usd');
  return out;
}

// The stored value with its well-formed days and entries, else an empty store: a missing, hand-edited or unknown value
// must not break a turn or the pane.
export function readSubagentStore(value) {
  if (!isRecord(value) || !(value.since === null || Number.isFinite(value.since))) return emptySubagentStore();
  if (value.version === 1) {
    const undated = undatedOf(value);
    return { version: 2, since: value.since, days: {}, ...(undated.agents ? { undated } : {}) };
  }
  if (value.version !== 2 || !isRecord(value.days)) return emptySubagentStore();
  const days = {};
  for (const [key, day] of Object.entries(value.days)) if (DAY.test(key) && isRecord(day)) days[key] = readDay(day);
  const undated = readSums(value.undated, UNDATED_SUMS);
  return { version: 2, since: value.since, days, ...(undated ? { undated } : {}) };
}

// A record whose first agent came before the last reset at `resetAt` (ms) reads as empty.
export const subagentsAfterReset = (record, resetAt) => afterResetOf(record, resetAt, emptySubagentStore);

const addSums = (into, from, sums) => {
  for (const sum of sums) into[sum] += from[sum];
};

function addDay(into, day) {
  for (const kind of ['routed', 'passed']) {
    const [sums, modelSums] = SUMS[kind];
    for (const [key, counts] of Object.entries(day[kind])) {
      const total = own(into[kind], key) ?? emptyCounts(sums);
      addSums(total, counts, sums);
      for (const [id, model] of Object.entries(counts.models)) {
        const sum = own(total.models, id) ?? zeros(modelSums);
        addSums(sum, model, modelSums);
        put(total.models, id, sum);
      }
      put(into[kind], key, total);
    }
  }
}

// Every session's record since the last reset added up day by day, since the earliest.
export function mergeSubagentStores(values, resetAt = null) {
  const merged = emptySubagentStore();
  for (const one of values.map((value) => subagentsAfterReset(readSubagentStore(value), resetAt))) {
    merged.since = earlierSince(merged.since, one.since);
    for (const [key, day] of Object.entries(one.days)) {
      merged.days[key] ??= emptySubagentDay();
      addDay(merged.days[key], day);
    }
    if (one.undated) {
      merged.undated ??= zeros(UNDATED_SUMS);
      addSums(merged.undated, one.undated, UNDATED_SUMS);
    }
  }
  return merged;
}

// A record's days inside `range` (periodRange in lib/usage.mjs) added up, with the agents per day, oldest first; null
// ends take the whole record and its undated totals.
export function summarizeSubagents(record, { from, to }) {
  const total = emptySubagentDay();
  const perDay = [];
  for (const key of Object.keys(record.days).sort()) {
    if ((from !== null && key < from) || (to !== null && key > to)) continue;
    const day = record.days[key];
    addDay(total, day);
    const agents = [...Object.values(day.routed), ...Object.values(day.passed)].reduce((n, c) => n + c.agents, 0);
    perDay.push([key, agents]);
  }
  const whole = from === null && to === null;
  return { ...total, perDay, undated: whole && record.undated ? record.undated : null };
}

// A routed type's or a pass-through's totals over its models: agents moved and their direction, routed cost and
// core's estimate (zero for a pass-through).
export function modelTotals(counts) {
  const out = zeros(ROUTED_MODEL_SUMS);
  for (const model of Object.values(counts.models)) for (const sum of ROUTED_MODEL_SUMS) out[sum] += model[sum] ?? 0;
  return out;
}

